<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {api,download} from '../services/api';import {usePage} from '../services/usePage';import Notice from '../components/Notice.vue';import PrivateImage from '../components/PrivateImage.vue';import StatusBadge from '../components/StatusBadge.vue'
const id=String(useRoute().params.id),row=ref<any>(null),reviews=ref<any[]>([]),decision=ref('confirmed'),note=ref(''),corrections=ref('[]');const {error,success,busy,act}=usePage();let timer:ReturnType<typeof setInterval>
async function load(){row.value=(await api.get(`inspections/${id}/`)).data;reviews.value=(await api.get(`inspections/${id}/reviews/`)).data}
onMounted(()=>{act(load);timer=setInterval(()=>{if(row.value&&['queued','running'].includes(row.value.job.state)&&!busy.value)act(load)},4000)});onBeforeUnmount(()=>clearInterval(timer))
const review=()=>act(async()=>{await api.post(`inspections/${id}/review/`,{decision:decision.value,note:note.value,annotations:decision.value==='confirmed'?row.value.detections:JSON.parse(corrections.value)});await load()},'Revisión registrada sin modificar la predicción original.')
</script>
<template><RouterLink to="/inspections" class="text-xs text-slate-500">← Historial</RouterLink><h1 class="heading mb-6 mt-3">{{row?.name||'Inspección'}}</h1><Notice :error="error" :success="success"/><template v-if="row"><div class="card mb-5 flex flex-wrap items-center justify-between gap-4"><div><StatusBadge :value="row.job.state"/><p class="mt-2 text-xs text-slate-500">{{row.model_name}} · Umbral {{row.job.config.confidence}}</p></div><div class="text-right"><p class="text-2xl font-semibold">{{row.job.state==='succeeded'?row.detections.length:'—'}} <span class="text-xs font-normal text-slate-500">lesiones detectadas</span></p><p class="mt-1 text-xs text-slate-400">Inferencia: {{row.inference_ms?.toFixed(1)||'—'}} ms · Total servidor: {{row.total_ms?.toFixed(1)||'—'}} ms</p></div></div><p v-if="row.job.error" class="mb-5 rounded-xl bg-red-50 p-4 text-sm text-red-700">{{row.job.error}} <RouterLink to="/jobs" class="underline">Ver trabajos</RouterLink></p><div class="grid gap-5 md:grid-cols-2"><section class="card"><h2 class="mb-4 font-semibold">Original</h2><PrivateImage :src="`inspections/${id}/file/`" class="aspect-square w-full object-contain"/></section><section class="card"><h2 class="mb-4 font-semibold">Resultado del modelo</h2><PrivateImage v-if="row.has_annotated" :src="`inspections/${id}/file/?annotated=1`" class="aspect-square w-full object-contain"/><p v-else class="py-20 text-center text-sm text-slate-400">Esperando resultado del worker…</p><button v-if="row.has_annotated" class="btn-secondary mt-3" @click="act(()=>download(`inspections/${id}/file/?annotated=1&download=1`,'deteccion.png'))">Descargar imagen</button></section></div><p class="my-5 text-xs text-amber-700">Cero detecciones no garantiza sanidad. Las predicciones no se convierten automáticamente en etiquetas de entrenamiento.</p><div v-if="row.detections.length" class="table-wrap mb-6 bg-white"><table class="data-table"><thead><tr><th>Clase</th><th>Confianza</th><th>Centro x/y</th><th>Ancho/alto</th></tr></thead><tbody><tr v-for="(b,i) in row.detections" :key="i"><td>roña · {{Number(i)+1}}</td><td>{{(b.confidence*100).toFixed(1)}}%</td><td>{{b.x.toFixed(4)}} / {{b.y.toFixed(4)}}</td><td>{{b.w.toFixed(4)}} / {{b.h.toFixed(4)}}</td></tr></tbody></table></div><form v-if="row.job.state==='succeeded'" @submit.prevent="review" class="card space-y-4"><h2 class="font-semibold">Revisión humana</h2><select v-model="decision" class="input max-w-xs"><option value="confirmed">Confirmar resultado</option><option value="corrected">Registrar corrección</option></select><textarea v-model="note" class="input" required placeholder="Observación del revisor"/><div v-if="decision==='corrected'"><label class="label">Cajas corregidas (JSON normalizado)</label><textarea v-model="corrections" class="input font-mono" rows="4"/><p class="text-xs text-slate-400">Formato: [{"class_id":0,"x":0.5,"y":0.5,"w":0.2,"h":0.2}]. Usa [] si no hay lesiones.</p></div><button class="btn" :disabled="busy">Guardar revisión</button><p v-for="r in reviews" :key="r.created_at" class="border-t border-slate-100 pt-2 text-xs text-slate-500">{{r.author__username}} · {{r.decision}} · {{r.note}}</p></form></template></template>
